content.text:
            dir_fixed = 1 if flow_fixed.src == router else -1
            old_samples = samples[(router, idx)]
            delta = [fixed_values[idx] - old for old in old_samples]
            for other_idx in self.incident_by_router[router]:
                if other_idx == idx or not remaining[other_idx]:
                    continue
                flow_other = self.flows[other_idx]
                dir_other = 1 if flow_other.src == router else -1
                coefficient = -dir_other * dir_fixed
                arr = raw_remainders[(router, other_idx)]
                if coefficient == 1:
                    for t in range(trials):
                        arr[t] += delta[t]
                elif coefficient == -1:
                    for t in range(trials):
                        arr[t] -= delta[t]
                # coefficient is always +/-1 for directed incidence.
                router_bands[(router, other_idx)] = _agreement_with_clamp(
                    arr, flow_other.capacity, epsilon
                )
                affected.add(other_idx)

        for other_idx in affected:
            rep, support_new = combine(other_idx)
            old_support = candidates[other_idx][1]
            candidates[other_idx] = (rep, support_new)
            if support_new != old_support:
                buckets[old_support] &= ~(1 << other_idx)
                buckets[support_new] |= (1 << other_idx)
            if support_new > current_max:
                current_max = support_new

    links = []
    for idx, flow in enumerate(self.flows):
        value = fixed_values[idx]
        n, d = _reduced(*fixed_confidences[idx])
        links.append((flow.src, flow.dst, value, n, d))

    counters: List[Tuple[str, int, int, int]] = []
    for idx, flow in enumerate(self.flows):
        _, _, value, n, d = links[idx]
        for key in flow.report_keys:
            counters.append((key, value, n, d))
    counters.sort(key=lambda item: item[0])

    return FrozenRepair(tuple(links), tuple(publication_order),
                        tuple(counters))

@staticmethod
def _publication(frozen: FrozenRepair, request_id: str,
                 cache_hit: bool) -> Dict[str, Any]:
    links = [[a, b, value, n, d]
             for a, b, value, n, d in frozen.links]
    order = [[a, b] for a, b in frozen.order]
    counters = {key: {"corrected": value,
                      "confidence": [n, d]}
                for key, value, n, d in frozen.counters}
    return {
        "op": "repair",
        "id": request_id,
        "cache_hit": cache_hit,
        "links": links,
        "order": order,
        "counters": counters,
    }

